mapper.select:
SELECT odp.id, odpd.id AS detailId, odp.code, odp.approve_status AS approveStatus, odp.invalid_status AS invalidStatus, odp.delivery_status AS deliveryStatus, odp.to_warehouse_id AS toWarehouseId, odp.to_warehouse_name AS toWarehouseName, odp.country, odp.country_name AS countryName, odpd.sku_id AS skuId, odpd.sku_no AS skuNo, odpd.is_combination AS isCombination, odpd.qty AS planQty, odp.create_user_id AS createUserId, odp.create_user_name AS createUserName, odp.approve_user_id AS approveUserId, odp.approve_user_name AS approveUserName, odp.create_time AS createTime, odp.approve_time AS approveTime, odpd.platform_sku as thirdWarehouseSku, odpd.platform_sku as platformSku, odpd.platform_spu as platformProductId, odpd.platform_fn_sku as platformFnSku, odp.type, odp.shop_id as shopId, odp.shop_name as shopName FROM wms_delivery_plan_detail odpd INNER JOIN wms_delivery_plan odp ON odp.id = odpd.main_id AND odpd.is_deleted = FALSE WHERE ${params.sqlMap.default} and odp.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
odp.create_time desc

SELECT odp.id, odp.code, odp.approve_status, odp.invalid_status, odp.delivery_status, odp.to_warehouse_id, odp.to_warehouse_name, odp.country, odp.country_name, odpd.sku_id, odpd.sku_no, odpd.is_combination, odpd.qty AS planQty, odp.create_user_id, odp.create_user_name, odp.approve_user_id, odp.approve_user_name, odp.create_time, odp.approve_time, op.code AS sourcePlatformCode, odpd.platform_sku as thirdWarehouseSku, odpd.platform_sku as platformSku, odpd.platform_spu as platformProductId, odpd.platform_fn_sku as platformFnSku, odp.type, odp.shop_id as shopId, odp.shop_name as shopName FROM wms_delivery_plan_detail odpd INNER JOIN wms_delivery_plan odp ON odp.id = odpd.main_id AND odpd.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = odp.to_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and odp.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
odp.create_time desc

SELECT odp.id AS sourceId, odpd.id AS sourceDetailId, odp.code AS sourceCode, odp.country, odp.country_name, odp.to_warehouse_id, odp.to_warehouse_name, odp.approve_status AS approveStatus, odpd.sku_id, odpd.sku_no, odpd.is_combination, odpd.qty AS planQty, odpd.qty AS deliveryQty, odpd.platform_sku as platformSku, odpd.platform_sku_name as platformSkuName, odp.type FROM wms_delivery_plan_detail odpd INNER JOIN wms_delivery_plan odp ON odp.id = odpd.main_id AND odpd.is_deleted = FALSE WHERE odp.is_deleted = FALSE
AND odp.id IN
#{id}
